//! Conversion of NTC thermistor ADC readings into resistance and temperature.

// Generated by `build.rs`: `R_PULLUP_OHMS`, `OVERSAMPLING`, `FULL_SCALE`, and `TABLE`, a list of
// (sum of `OVERSAMPLING` ADC readings, temperature in tenths of °C) sorted by ascending ADC sum,
// computed for a pull-up of `R_PULLUP_OHMS`.
include!(concat!(env!("OUT_DIR"), "/ntc_table.rs"));

/// Returns the reading that a sum of [`OVERSAMPLING`] ADC readings stands for, and the rest up to
/// [`FULL_SCALE`]. The thermistor resistance is `pull-up × reading / rest`.
///
/// Returns [`None`] if the reading is at full scale, e.g., when the thermistor is disconnected.
#[must_use]
pub fn reading(adc_sum: u16) -> Option<(u32, u32)> {
    // ADC code `n` covers inputs around `n + 0.5`, hence the half-code offset per reading.
    let reading = u32::from(adc_sum) + u32::from(OVERSAMPLING / 2);
    // Readings at the highest code leave exactly that offset, so the pin sits at the reference and
    // nothing pulls it down.
    let rest = FULL_SCALE
        .checked_sub(reading)
        .filter(|&r| r > u32::from(OVERSAMPLING / 2))?;
    Some((reading, rest))
}

/// Returns the resistance of the thermistor, in ohms, for a sum of [`OVERSAMPLING`] ADC readings
/// taken with a `pullup_ohms` pull-up.
///
/// Returns [`None`] if the reading is at full scale, e.g., when the thermistor is disconnected.
#[must_use]
pub fn resistance_ohms(adc_sum: u16, pullup_ohms: u16) -> Option<u32> {
    let (reading, rest) = reading(adc_sum)?;
    // At most 65 535 × 65 504 + 32 767, which fits a `u32`. This math avoids `u64`, whose
    // division routines take about 3 KB of flash on AVR.
    Some((u32::from(pullup_ohms) * reading + rest / 2) / rest)
}

/// Returns the pull-up, in ohms, with which a sum of [`OVERSAMPLING`] ADC readings shows
/// `known_ohms` as the thermistor resistance.
///
/// Returns [`None`] if the reading is at full scale or the pull-up doesn't fit a `u16`.
#[must_use]
pub fn pullup_ohms_for(adc_sum: u16, known_ohms: u32) -> Option<u16> {
    let (reading, rest) = reading(adc_sum)?;
    // pull-up = known × rest / reading, split so that every product fits a `u32`: the quotient
    // must stay below 65 536, and the remainder is below `reading`.
    let quotient = known_ohms / reading;
    let remainder = known_ohms % reading;
    let whole = u16::try_from(quotient).ok()?;
    let ohms = u32::from(whole) * rest + (remainder * rest + reading / 2) / reading;
    u16::try_from(ohms).ok()
}

/// Returns the temperature, in tenths of a degree Celsius, for a sum of [`OVERSAMPLING`] ADC
/// readings taken with a `pullup_ohms` pull-up.
///
/// Returns [`None`] outside of the range covered by the table, e.g., when the thermistor is
/// disconnected (reading close to full scale) or shorted (reading close to zero).
#[must_use]
pub fn temperature_decicelsius(adc_sum: u16, pullup_ohms: u16) -> Option<u16> {
    let adc_sum = if pullup_ohms == R_PULLUP_OHMS {
        adc_sum
    } else {
        rescale(adc_sum, pullup_ohms)?
    };
    TABLE.windows(2).find_map(|pair| {
        let &[(hot_sum, hot_temp), (cold_sum, cold_temp)] = pair else {
            return None;
        };
        if !(hot_sum..=cold_sum).contains(&adc_sum) {
            return None;
        }
        // Linear interpolation between both entries, rounded to the nearest tenth of a degree.
        let span = u32::from(cold_sum - hot_sum);
        let offset = u32::from(adc_sum - hot_sum);
        let delta = u32::from(hot_temp - cold_temp);
        let decrease = (delta * offset + span / 2).checked_div(span)?;
        hot_temp.checked_sub(u16::try_from(decrease).ok()?)
    })
}

/// Returns the ADC sum that the table's pull-up, [`R_PULLUP_OHMS`], would give for the thermistor
/// resistance that `adc_sum` shows with a `pullup_ohms` pull-up.
fn rescale(adc_sum: u16, pullup_ohms: u16) -> Option<u16> {
    let (reading, rest) = reading(adc_sum)?;
    // With the table's pull-up, the same resistance gives the reading
    // `FULL_SCALE × actual / (actual + nominal)`. Each product fits a `u32`, and halving both
    // keeps their sum within one.
    let actual = u32::from(pullup_ohms) * reading / 2;
    let nominal = u32::from(R_PULLUP_OHMS) * rest / 2;
    // Divides by `total / FULL_SCALE` instead of multiplying by `FULL_SCALE`, and only the smaller
    // part, deriving the other one: that keeps the result precise at both ends of the range,
    // where it matters.
    let divisor = ((actual + nominal + FULL_SCALE / 2) / FULL_SCALE).max(1);
    let rescaled = if actual <= nominal {
        (actual + divisor / 2) / divisor
    } else {
        FULL_SCALE.saturating_sub((nominal + divisor / 2) / divisor)
    };
    u16::try_from(rescaled.checked_sub(u32::from(OVERSAMPLING / 2))?).ok()
}
